# A numeric token that is a syntactically valid array index (no leading
# zeros, no signs) but whose integer value exceeds Python's integer string
# conversion digit limit. 4300 is the default limit; use a comfortably
# larger value so the test is robust across interpreters.
OVERSIZED_INDEX = '1' + '0' * 5000


class OversizedIndexResolveTests(unittest.TestCase):

