)


class TestAddUppercaseChar(unittest.TestCase):

    def test_processes_every_original_pair(self):
        # Every original pair must get an uppercase variant.
        original = [('a', 'x'), ('b', 'y'), ('c', 'z')]
        result = add_uppercase_char(list(original))
        for char, xlate in original:
            self.assertIn((char.upper(), xlate.capitalize()), result)

    def test_later_pairs_get_uppercase_variants(self):
        # The bug returned after the first pair, so later pairs were skipped.
        original = [('a', 'x'), ('b', 'y'), ('c', 'z')]
        result = add_uppercase_char(list(original))
        self.assertIn(('B', 'Y'), result)
        self.assertIn(('C', 'Z'), result)

    def test_capitalization_convention_unchanged(self):
        original = [('a', 'x'), ('b', 'y')]
        result = add_uppercase_char(list(original))
        self.assertIn(('A', 'X'), result)
        self.assertIn(('B', 'Y'), result)

    def test_existing_uppercase_entries_retained_without_duplicates(self):
        original = [('a', 'x'), ('A', 'X')]
        result = add_uppercase_char(list(original))
        self.assertEqual(result.count(('A', 'X')), 1)
        self.assertIn(('a', 'x'), result)

    def test_returns_list_of_tuples(self):
        result = add_uppercase_char([('a', 'x')])
        self.assertIsInstance(result, list)
        for item in result:
            self.assertIsInstance(item, tuple)
            self.assertEqual(len(item), 2)


